import java.util.*;
class RiverSplitGeometryTest {
 static TerraForge.World world(int n,int ox,int oz){var w=new TerraForge.World(n,62,83);Arrays.fill(w.height,92);var e=w.environment;e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];e.snow=new float[n*n];e.resolvedRiverChannels=true;for(int z=0;z<n;z++)for(int x=0;x<n;x++){int gx=x+ox,gz=z+oz,i=z*n+x;if(gz>=250&&gz<=262&&gx>100&&gx<410){e.water[i]=90;e.height[i]=87;e.river[i]=1;}}return w;}
 public static void main(String[]args){var split=RiverFlow.split(100,new RiverFlow.Arm(4,4,.01,.028),new RiverFlow.Arm(4,1.5,.01,.06));var plan=new RiverFlow.BranchPlan(split,90,6,3);var bar=new RiverRibbon.SedimentIsland(256,256,20,2,0);var full=world(512,0,0);RiverRibbon.island(full,0,0,62,bar,plan);var e=full.environment;int left=0,right=0;for(int z=245;z<=267;z++){int i=z*512+256;if(e.waterY(i,62)>Math.round(e.height[i])){if(z>256)left++;if(z<256)right++;}}if(left<=right||right<1||e.waterY(256*512+256,62)>Math.round(e.height[256*512+256]))throw new AssertionError("Split geometry ignores shares: "+left+" / "+right);if(e.waterY(256*512+220,62)<=Math.round(e.height[256*512+220])||e.waterY(256*512+292,62)<=Math.round(e.height[256*512+292]))throw new AssertionError("Split does not reconnect");
  for(int rz=0;rz<2;rz++)for(int rx=0;rx<2;rx++){var tile=world(256,rx*256,rz*256);RiverRibbon.island(tile,rx*256,rz*256,62,bar,plan);for(int z=0;z<256;z++)for(int x=0;x<256;x++){int a=z*256+x,b=(z+rz*256)*512+x+rx*256;if(tile.height[a]!=full.height[b]||tile.environment.water[a]!=e.water[b]||tile.environment.river[a]!=e.river[b])throw new AssertionError("Split differs across region seam");}}
  var bank=new TerrainGraph.Node(1,TerrainGraph.Type.RIVER_BANKS,0,0);var repaired=RiverBanks.apply(bank,e,512,512,62,83,0,0,()->false);if(repaired.waterY(253*512+256,62)<=Math.round(repaired.height[253*512+256])||repaired.waterY(259*512+256,62)<=Math.round(repaired.height[259*512+256]))throw new AssertionError("Bank processing closed split arm");
  System.out.println("PASS: larger-flow arm is wider/deeper, island remains dry, arms reconnect and block geometry matches across four tile seams");
 }
}
